/** Heights of the presets in pixels, per breakpoint. */
export const HEIGHT_PRESETS = {
  s: {
    desktop: 160,
    tablet: 140,
    mobile: 120
  },
  m: {
    desktop: 200,
    tablet: 170,
    mobile: 140
  },
  l: {
    desktop: 240,
    tablet: 200,
    mobile: 160
  }
};
function heightVariables(height) {
  if (height.preset === 'auto') {
    return {};
  }
  const values = height.preset === 'custom' ? height : HEIGHT_PRESETS[height.preset];
  return {
    '--wch-height-desktop': `${values.desktop}px`,
    '--wch-height-tablet': `${values.tablet}px`,
    '--wch-height-mobile': `${values.mobile}px`
  };
}

/**
 * Text sizes in rem, on mobile then on tablet and desktop. `m` is the size
 * of the core.
 */
export const TEXT_SIZES = {
  title: {
    s: [0.875, 1.125],
    m: [1, 1.375],
    l: [1.25, 1.75],
    xl: [1.5, 2.25]
  },
  subtitle: {
    s: [0.75, 0.8125],
    m: [0.8125, 0.9375],
    l: [0.9375, 1.125]
  }
};
function textVariables(text) {
  const [titleMobile, title] = TEXT_SIZES.title[text.titleSize];
  const [subtitleMobile, subtitle] = TEXT_SIZES.subtitle[text.subtitleSize];
  return {
    '--wch-title-size': `${title}rem`,
    '--wch-title-size-mobile': `${titleMobile}rem`,
    '--wch-subtitle-size': `${subtitle}rem`,
    '--wch-subtitle-size-mobile': `${subtitleMobile}rem`,
    ...(text.color ? {
      '--wch-text-color': text.color
    } : {})
  };
}

/** Social icon sizes in pixels. */
export const SOCIAL_SIZES = {
  xs: 14,
  s: 18,
  m: 24
};
function socialsVariables(socials) {
  return {
    '--wch-socials-size': `${SOCIAL_SIZES[socials.size]}px`,
    ...(socials.color ? {
      '--wch-socials-color': socials.color
    } : {})
  };
}

/** Displayed logo heights in pixels (reduced on mobile by the CSS). */
export const LOGO_HEIGHTS = {
  s: 64,
  m: 96,
  l: 128
};

/** A linear gradient from a corner goes to the opposite one. */
const OPPOSITE_CORNERS = {
  'top-left': 'bottom right',
  'top-right': 'bottom left',
  'bottom-left': 'top right',
  'bottom-right': 'top left'
};
const stopList = stops => stops.map(stop => `${stop.color} ${stop.at}%`).join(', ');

/** The CSS background of the overlay, or null when there is none. */
function overlayBackground(overlay) {
  switch (overlay.type) {
    case 'solid':
      return overlay.color;
    case 'gradient':
      {
        const direction = 'corner' in overlay ? `to ${OPPOSITE_CORNERS[overlay.corner]}` : `${overlay.angle}deg`;
        return `linear-gradient(${direction}, ${stopList(overlay.stops)})`;
      }
    case 'radial':
      return `radial-gradient(${overlay.shape} at ${overlay.position.replace('-', ' ')}, ${stopList(overlay.stops)})`;
    case 'corners':
      // Each color fades out from its corner: the four meet and blend in the middle.
      return [['top left', overlay.topLeft], ['top right', overlay.topRight], ['bottom left', overlay.bottomLeft], ['bottom right', overlay.bottomRight]].map(([corner, color]) => `radial-gradient(at ${corner}, ${color}, transparent 70%)`).join(', ');
    default:
      return null;
  }
}

/**
 * The CSS variables of a resolved config, set on the hero element. Values
 * come from a validated config, never from raw CSS.
 */
export function heroStyle(config) {
  const overlay = config.overlay ? overlayBackground(config.overlay) : null;
  return {
    ...(config.height ? heightVariables(config.height) : {}),
    ...(config.background?.image ? {
      '--wch-bg-position': `${config.background.position.x}% ${config.background.position.y}%`
    } : {}),
    ...(overlay ? {
      '--wch-overlay': overlay
    } : {}),
    ...(config.textStyle ? textVariables(config.textStyle) : {}),
    ...(config.logo?.image ? {
      '--wch-logo-height': `${LOGO_HEIGHTS[config.logo.size]}px`
    } : {}),
    ...(config.socials?.items.length ? socialsVariables(config.socials) : {})
  };
}
flarum.reg.add('walsgit-custom-heroes', 'common/heroStyle', { HEIGHT_PRESETS: HEIGHT_PRESETS,TEXT_SIZES: TEXT_SIZES,SOCIAL_SIZES: SOCIAL_SIZES,LOGO_HEIGHTS: LOGO_HEIGHTS,heroStyle: heroStyle, });